solution.python:
from typing import Optional

# ListNode is supplied by the LeetCode judge.
class Solution:
    def hasCycle(self, head: Optional["ListNode"]) -> bool:
        slow = fast = head

        while fast is not None and fast.next is not None:
            slow = slow.next
            fast = fast.next.next
            if slow is fast:
                return True

        return False
